import Header from '../components/Header';
import Footer from '../components/Footer';
import { useParams } from 'react-router-dom';
import { useState, useEffect } from 'react';
import '../styles/Detail.css';
import '../styles/home.css';

function Detail() {
    const { idArticle } = useParams();
    const [article, setArticle] = useState({});
    const [isEditing, setIsEditing] = useState(false);
    const [updatedItem, setUpdatedItem] = useState({
        name: '',
        price: 0,
        description: '',
        image: '',
        onSale: false
    });

    useEffect(() => {
            fetch(`http://localhost:3001/${idArticle}`)
                .then(response => response.json())
                .then(data => {
                    setArticle(data);
                    setUpdatedItem(data);
                })
                .catch(error => {
                    console.error('Erreur lors de la récupération de l\'article :', error);
                });
    }, []);

    const handleInputChange = (e) => {
        const { name, value } = e.target;
        setUpdatedItem(prevState => ({
            ...prevState,
            [name]: value
        }));
    };

    return (
    <div className="home">
        <Header />
        {!isEditing ? (
            <div className="detail-container">
                <h1>Détail du produit : {idArticle}</h1>
                <img src={article.image} alt={article.name} className="detail-image"/>
                <p><b>Nom :</b> {article.name}</p>
                <p><b>Prix :</b> {article.price}€</p>
                <p><b>Description :</b> {article.description}</p>
            </div>
        ) : (
            <div className="detail-container">
                <input type="text" value={updatedItem.name} onChange={handleInputChange} />
                <button onClick={handleUpdateItem}>Enregistrer</button>
                <button onClick={() => setIsEditing(false)}>Annuler</button>
            </div>
        )}
        
        <Footer />
    </div>
        
    );
}
export default Detail;
